const config = { enabled: false, backendBaseUrl: '', standardHours: 24, expeditedHours: 12, bumpCents: 1277, replicateModel: 'resemble-ai/chatterbox', voiceReferenceUrl: '', voiceVersion: '', audioSharesOrderDeadline: true };
